sys_ws_operation.operation_script:
(function process( /*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    var body = request.body.data;
    var jiraId = body.issue.id;
    var summary = body.issue.fields.summary;
    var comment = body.comment.body;
    var status = body.issue.fields.status.name;

    gs.info("Hello JIRA " + JSON.stringify(body));
    gs.info("Hello JIRA status " + status);
    var grInc = new GlideRecord("incident");
    grInc.addQuery("x_2129719_servic_0_jira_id", jiraId);
    grInc.addQuery("active", true);
    grInc.query();
    if (grInc.next()) {
        grInc.short_description = summary;
        if (comment) {
            grInc.comments = comment;
        }

        if (status == "To Do") {
            grInc.state = '1';
        }
        if (status == "In Progress") {
            grInc.state = '2';
        }
        if (status == "In Review") {
            grInc.state = '6';
        }

        grInc.update();
    }


})(request, response);
